(()=>{var o=document.getElementById("lightbox"),c=o.querySelector(".lightbox__image");function s(e){let n=(e.getAttribute("srcset")||"").split(",").map(t=>t.trim().split(/\s+/)).filter(([t])=>t).map(([t,r])=>({url:t,width:parseInt(r,10)||0}));return n.length===0?e.currentSrc||e.src:n.reduce((t,r)=>r.width>t.width?r:t).url}function l(e){return e instanceof HTMLImageElement&&e.closest(".post-content, .post-header, .content-section")&&!e.closest("a, .lightbox")}document.addEventListener("click",e=>{let n=e.target;l(n)&&(c.src=s(n),c.alt=n.alt,document.documentElement.style.overflow="hidden",o.showModal())});o.addEventListener("click",()=>o.close());o.addEventListener("close",()=>{document.documentElement.style.removeProperty("overflow"),c.removeAttribute("src")});})();
